"""Record actual technical and sampled visual review evidence for Utkomststod."""
from pathlib import Path
import json,yaml,hashlib,re,difflib
ROOT=Path(__file__).resolve().parents[3];SID='hb-c10-utkomststod';EP=ROOT/'studio/episodes'/SID;MEDIA=ROOT/'studio/media'/SID;d=yaml.safe_load((EP/'script.yaml').read_text());r=json.loads((EP/'render.json').read_text());check=json.loads((EP/'render-check.json').read_text());assert r['sha256']==check['sha256']==hashlib.sha256((ROOT/r['output']).read_bytes()).hexdigest()
asr=json.loads((MEDIA/'narration/asr.json').read_text());metrics=json.loads((MEDIA/'narration/metrics.json').read_text());assert len(asr)==len(metrics)==len(d['sentences'])==10
trans={Path(a['file']).stem:a for a in asr};diagnostics=[]
for row,m in zip(d['sentences'],metrics):
    a=trans[row['sentence_id']];assert a['sha256']==hashlib.sha256((ROOT/m['path']).read_bytes()).hexdigest();norm=lambda s:re.sub(r'\W+','',s.lower());ratio=difflib.SequenceMatcher(None,norm(m['text']),norm(a['asr_text'])).ratio();diagnostics.append(dict(sentence_id=row['sentence_id'],tts_input=m['text'],asr_text=a['asr_text'],text_similarity=ratio,review_priority='Finnish benefit name pronunciation; ASR is not a listening review' if 'täydentävä' in row['sv'] else 'Source compounds and inflection differences need whole-video listening' if ratio<.97 else 'No large automatic difference; listening still pending'))
(EP/'audio-diagnostics.json').write_text(json.dumps(dict(clip_count=10,all_current_wav_hashes_checked=True,diagnostics=diagnostics,listening=False),ensure_ascii=False,indent=2)+'\n')
coverage=json.loads((EP/'picture-coverage.json').read_text());assert coverage['picture_fraction']==1
report=dict(section_id=SID,status='preview_ready',output=r['output'],seconds=r['seconds'],sha256=r['sha256'],source_section_sha256=d['source_section_sha256'],translation_file_sha256=d['translation_file_sha256'],pairs=10,actual_body_picture_fraction=1.,distinct_pictures=10,photographs=2,original_source_specific_diagrams=8,full_decode=check['full_decode'],encoded_audio_correlation=check['encoded_audio_matches_mix']['correlation'],sampled_frames=['export-frame-06.png','export-frame-11.png'],whole_video_listening=False,physical_device_playback=False,user_acceptance=False,issues=['Finnish benefit names in sentence hb-c10-u0025-s001 require listening; ASR produced garbled Finnish names.','Dense long sentence hb-c10-u0023-s001 uses permitted40/34fonts; fullscreen landscape recommended for phone review.'])
(EP/'production-handoff.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
b=yaml.safe_load((EP/'brief.yaml').read_text());b.update(production_status='preview_ready',output_path=r['output'],issues=['Verified complete export; whole-video listening/user acceptance pending.']+report['issues']);(EP/'brief.yaml').write_text(yaml.safe_dump(b,allow_unicode=True,sort_keys=False,width=100))
(EP/'review.md').write_text(f'''# Episode review\n\nSection ID: {SID}\n\nProducer/date: Chapter10worker,2026-11-03\n\nPreview: `{r['output']}` — 3:06.708,1920×1080/24fps.\n\n- [x] Every10source sentence/list fragment once in stored source order; exact Swedish/Russian and current section/chapter-heading reviews validated.\n- [x] Ten full local F1clips retained with actual inputs/settings, measured durations and current hashes.\n- [x] ASR diagnostic transcripts exist for all10currentWAVs; see audio-diagnostics.json.\n- [x] Pronunciation overrides remain separate from exact display text.\n- [x] All14planned/exported cards fit; dense sentence6uses permitted40/34fonts and sentence9uses44/36.\n- [x] Sampled1080p/laptop960px/phone640px static previews inspected; no clipping or orphan captions. Dense lists need fullscreen landscape reading. These are image-size checks, not physical device playback.\n- [x] Ten distinct relevant foreground pictures cover100%bodytimeline:2licensed concrete photographs and8individually composed source-specific diagrams. No invented benefit amounts or legal conditions.\n- [x] Full source/media credits and canonical sidecar retained; actual InfoFinland publisher corrected before final export.\n- [x] Complete export decodes:4481frames,186.708seconds; audio and video streams present; current mix correlation{check['encoded_audio_matches_mix']['correlation']:.6f}.\n- [x] Background continuous-motion metrics checked across boundaries; 5secondopeningpixelchange{check['opening_background_mean_pixel_change']['5.0']:.2f},10second{check['opening_background_mean_pixel_change']['10.0']:.2f}.\n- [ ] Whole-video voice/Swedish accent/Finnish name pronunciation listened to and accepted.\n- [ ] Music mix heard on headphones/ordinaryspeakers.\n- [ ] Physical phone/laptop playback.\n- [ ] Complete export watched/heard end-to-end and accepted by user.\n\n## Findings\n\nThe Finnish benefit names in hb-c10-u0025-s001 produced a large ASR difference. This is explicitly a listening priority; automated checks do not certify pronunciation. Other compound/inflection diagnostics are retained without speculative repeated retakes.\n\nThe first partial render was cancelled only by its exact ownedPID after a copied closingpublisher was found. Final closingcard credits the actual InfoFinland source; sidecar always derived actual source snapshot. Final export hash: `{r['sha256']}`.\n\nNo picture-coverage exception. No commit/upload/useracceptance claimed.\n''')
print(json.dumps(report,ensure_ascii=False))
